        const originInitialized = rawFloor?.originInitialized === true;
        const normalizedName = normalizeLabelText(
          rawFloor?.name,
          floorNameForIndex(rawFloorIndex),
          24
        );
        const floorName =
          normalizedName === rawFloorIndex + 1 + "层"
            ? floorNameForIndex(rawFloorIndex)
            : normalizedName;
