    if (forceOrthogonal && anchor) {
      const axisLockedResult = axisLockedPoint(snapPointInput, anchor);
      return {
        ...axisLockedResult,
        kind: "axis",
        distance: distance(snapPointInput, axisLockedResult.point)
      };
    }
